WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/43.0/connection.js")} // Load Salesforce AJAX Toolkit

// Confirm before proceeding
var proceed = confirm("Apakah anda yakin ingin membatalkan transaksi ini?");
if (proceed) {
    // Get current record ID
    var recordId = "{!Log_Book_Activitiy_Detail__c.Id}";

    // Create sObject and set field
    var log = new sforce.SObject("Log_Book_Activitiy_Detail__c");
    log.Id = recordId;
    log.Canceled__c = true;

    // Update the record
    var result = sforce.connection.update([log]);

    if (result[0].success === "true") {
        alert("Transaksi berhasil dibatalkan.");
        window.location.reload(); // Refresh the page
    } else {
        alert("Error cancelling activity: " + result[0].errors.message);
    }
}
